package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class EvidenceFrameworkPermissionGuardTest{@Test void exactActionAndAgencyScopeAreRequired(){var client=mock(AdministrativeAuthorizationClient.class);var guard=new EvidenceFrameworkPermissionGuard(client);when(client.resolve(EvidenceFrameworkPermissionGuard.FRAMEWORK,"token")).thenReturn(permission(true,true,false,true,true,PermissionDataScope.AGENCY_WIDE));assertThatCode(()->guard.require(PrimeHrAction.PUBLISH,"token")).doesNotThrowAnyException();assertThatThrownBy(()->guard.require(PrimeHrAction.EDIT,"token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(EvidenceFrameworkPermissionGuard.FRAMEWORK,"assigned")).thenReturn(permission(true,true,true,true,true,PermissionDataScope.ASSIGNED_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.ACCESS,"assigned")).isInstanceOf(AccessDeniedException.class);}private EffectiveFeaturePermission permission(boolean access,boolean add,boolean edit,boolean delete,boolean publish,PermissionDataScope scope){return new EffectiveFeaturePermission("feature",false,access,add,edit,delete,publish,false,false,false,false,false,scope);}}
